import{_ as i,a0 as t,w as c,s as d,ao as r,I as p,x as a,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"理解多區域配置中的 firewalld | LCTT x X-CMD","titleTemplate":false,"description":"理解多區域配置中的 firewalld | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解多區域配置中的 firewalld | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解多區域配置中的 firewalld | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20170202 Understanding Firewalld in Multi-Zone Configurations","title":"理解多區域配置中的 firewalld","tag":"201711","desc":""},"relativePath":"201711/20170202 Understanding Firewalld in Multi-Zone Configurations.md","filePath":"[post].md"}'),o={name:"201711/20170202 Understanding Firewalld in Multi-Zone Configurations.md"};function h(u,s,g,b,f,k){const n=t("Link");return c(),d("div",null,[s[13]||(s[13]=r(`<h1 id="理解多區域配置中的-firewalld" tabindex="-1">理解多區域配置中的 firewalld <a class="header-anchor" href="#理解多區域配置中的-firewalld" aria-label="Permalink to “理解多區域配置中的 firewalld”">​</a></h1><p>現在的新聞裏充斥着服務器被攻擊和數據失竊事件。對於一個閲讀過安全公告Blog的人來説，通過訪問錯誤配置的服務器，利用最新暴露的安全漏洞或通過竊取的密碼來獲得系統控制權，並不是件多困難的事情。在一個典型的 Linux 服務器上的任何互聯網服務都可能存在漏洞，允許未經授權的系統訪問。</p><p>因為在應用程序層面上強化系統以防範任何可能的威脅是不可能做到的事情，而防火牆可以通過限制對系統的訪問提供了安全保證。防火牆基於源 IP、目標端口和協議來過濾入站包。因為這種方式中，僅有幾個 IP/端口/協議的組合與系統交互，而其它的方式做不到過濾。</p><p>Linux 防火牆是通過 netfilter 來處理的，它是內核級別的框架。這十幾年來，iptables 被作為 netfilter 的用户態抽象層（LCTT 譯註： userland，一個基本的 UNIX 系統是由 kernel 和 userland 兩部分構成，除 kernel 以外的稱為 userland）。iptables 將包通過一系列的規則進行檢查，如果包與特定的 IP/端口/協議的組合匹配，規則就會被應用到這個包上，以決定包是被通過、拒絕或丟棄。</p><p>Firewalld 是最新的 netfilter 用户態抽象層。遺憾的是，由於缺乏描述多區域配置的文檔，它強大而靈活的功能被低估了。這篇文章提供了一個示例去改變這種情況。</p><h3 id="firewalld-的設計目標" tabindex="-1">Firewalld 的設計目標 <a class="header-anchor" href="#firewalld-的設計目標" aria-label="Permalink to “Firewalld 的設計目標”">​</a></h3><p>firewalld 的設計者認識到大多數的 iptables 使用案例僅涉及到幾個單播源 IP，僅讓每個符合白名單的服務通過，而其它的會被拒絕。這種模式的好處是，firewalld 可以通過定義的源 IP 和/或網絡接口將入站流量分類到不同<ruby>區域<rt>zone</rt></ruby>。每個區域基於指定的準則按自己配置去通過或拒絕包。</p><p>另外的改進是基於 iptables 進行語法簡化。firewalld 通過使用服務名而不是它的端口和協議去指定服務，使它更易於使用，例如，是使用 samba 而不是使用 UDP 端口 137 和 138 和 TCP 端口 139 和 445。它進一步簡化語法，消除了 iptables 中對語句順序的依賴。</p><p>最後，firewalld 允許交互式修改 netfilter，允許防火牆獨立於存儲在 XML 中的永久配置而進行改變。因此，下面的的臨時修改將在下次重新加載時被覆蓋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd &lt;some modification&gt;</span></span></code></pre></div><p>而，以下的改變在重加載後會永久保存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent &lt;some modification&gt;</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><h3 id="區域" tabindex="-1">區域 <a class="header-anchor" href="#區域" aria-label="Permalink to “區域”">​</a></h3><p>在 firewalld 中最上層的組織是區域。如果一個包匹配區域相關聯的網絡接口或源 IP/掩碼 ，它就是區域的一部分。可用的幾個預定義區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-zones</span></span>
<span class="line"><span>block dmz drop external home internal public trusted work</span></span></code></pre></div><p>任何配置了一個<strong>網絡接口</strong>和/或一個<strong>源</strong>的區域就是一個<ruby>活動區域<rt>active zone</rt></ruby>。列出活動的區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-active-zones</span></span>
<span class="line"><span>public</span></span>
<span class="line"><span>  interfaces: eno1 eno2</span></span></code></pre></div><p><strong>Interfaces</strong> （接口）是系統中的硬件和虛擬的網絡適配器的名字，正如你在上面的示例中所看到的那樣。所有的活動的接口都將被分配到區域，要麼是默認的區域，要麼是用户指定的一個區域。但是，一個接口不能被分配給多於一個的區域。</p><p>在缺省配置中，firewalld 設置所有接口為 public 區域，並且不對任何區域設置源。其結果是，<code>public</code> 區域是唯一的活動區域。</p><p><strong>Sources</strong> （源）是入站 IP 地址的範圍，它也可以被分配到區域。一個源（或重疊的源）不能被分配到多個區域。這樣做的結果是產生一個未定義的行為，因為不清楚應該將哪些規則應用於該源。</p><p>因為指定一個源不是必需的，任何包都可以通過接口匹配而歸屬於一個區域，而不需要通過源匹配來歸屬一個區域。這表示通過使用優先級方式，優先到達多個指定的源區域，稍後將詳細説明這種情況。首先，我們來檢查 <code>public</code> 區域的配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=public --list-all</span></span>
<span class="line"><span>public (default, active)</span></span>
<span class="line"><span>  interfaces: eno1 eno2</span></span>
<span class="line"><span>  sources:</span></span>
<span class="line"><span>  services: dhcpv6-client ssh</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --get-target</span></span>
<span class="line"><span>default</span></span></code></pre></div><p>逐行説明如下：</p><ul><li><code>public (default, active)</code> 表示 <code>public</code> 區域是默認區域（當接口啓動時會自動默認），並且它是活動的，因為，它至少有一個接口或源分配給它。</li><li><code>interfaces: eno1 eno2</code> 列出了這個區域上關聯的接口。</li><li><code>sources:</code> 列出了這個區域的源。現在這裏什麼都沒有，但是，如果這裏有內容，它們應該是這樣的格式 xxx.xxx.xxx.xxx/xx。</li><li><code>services: dhcpv6-client ssh</code> 列出了允許通過這個防火牆的服務。你可以通過運行 <code>firewall-cmd --get-services</code> 得到一個防火牆預定義服務的詳細列表。</li><li><code>ports:</code> 列出了一個允許通過這個防火牆的目標端口。它是用於你需要去允許一個沒有在 firewalld 中定義的服務的情況下。</li><li><code>masquerade: no</code> 表示這個區域是否允許 IP 偽裝。如果允許，它將允許 IP 轉發，它可以讓你的計算機作為一個路由器。</li><li><code>forward-ports:</code> 列出轉發的端口。</li><li><code>icmp-blocks:</code> 阻塞的 icmp 流量的黑名單。</li><li><code>rich rules:</code> 在一個區域中優先處理的高級配置。</li><li><code>default</code> 是目標區域，它決定了與該區域匹配而沒有由上面設置中顯式處理的包的動作。</li></ul><h3 id="一個簡單的單區域配置示例" tabindex="-1">一個簡單的單區域配置示例 <a class="header-anchor" href="#一個簡單的單區域配置示例" aria-label="Permalink to “一個簡單的單區域配置示例”">​</a></h3><p>如果只是簡單地鎖定你的防火牆。簡單地在刪除公共區域上當前允許的服務，並重新加載：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=public --remove-service=dhcpv6-client</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --remove-service=ssh</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>在下面的防火牆上這些命令的結果是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=public --list-all</span></span>
<span class="line"><span>public (default, active)</span></span>
<span class="line"><span>  interfaces: eno1 eno2</span></span>
<span class="line"><span>  sources:</span></span>
<span class="line"><span>  services:</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --get-target</span></span>
<span class="line"><span>default</span></span></code></pre></div><p>本着儘可能嚴格地保證安全的精神，如果發生需要在你的防火牆上臨時開放一個服務的情況（假設是 ssh），你可以增加這個服務到當前會話中（省略 <code>--permanent</code>），並且指示防火牆在一個指定的時間之後恢復修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=public --add-service=ssh --timeout=5m</span></span></code></pre></div><p>這個 <code>timeout</code> 選項是一個以秒（<code>s</code>）、分（<code>m</code>）或小時（<code>h</code>）為單位的時間值。</p><h3 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to “目標”">​</a></h3><p>當一個區域處理它的源或接口上的一個包時，但是，沒有處理該包的顯式規則時，這時區域的<ruby>目標<rt>target</rt></ruby>決定了該行為：</p><ul><li><code>ACCEPT</code>：通過這個包。</li><li><code>%%REJECT%%</code>：拒絕這個包，並返回一個拒絕的回覆。</li><li><code>DROP</code>：丟棄這個包，不回覆任何信息。</li><li><code>default</code>：不做任何事情。該區域不再管它，把它踢到“樓上”。</li></ul><p>在 firewalld 0.3.9 中有一個 bug （已經在 0.3.10 中修復），對於一個目標是除了“default”以外的源區域，不管允許的服務是什麼，這的目標都會被應用。例如，一個使用目標 <code>DROP</code> 的源區域，將丟棄所有的包，甚至是白名單中的包。遺憾的是，這個版本的 firewalld 被打包到 RHEL7 和它的衍生版中，使它成為一個相當常見的 bug。本文中的示例避免了可能出現這種行為的情況。</p><h3 id="優先權" tabindex="-1">優先權 <a class="header-anchor" href="#優先權" aria-label="Permalink to “優先權”">​</a></h3><p>活動區域中扮演兩個不同的角色。關聯接口行為的區域作為接口區域，並且，關聯源行為的區域作為源區域（一個區域能夠扮演兩個角色）。firewalld 按下列順序處理一個包：</p><ol><li>相應的源區域。可以存在零個或一個這樣的區域。如果這個包滿足一個<ruby>富規則<rt>rich rule</rt></ruby>、服務是白名單中的、或者目標沒有定義，那麼源區域處理這個包，並且在這裏結束。否則，向上傳遞這個包。</li><li>相應的接口區域。肯定有一個這樣的區域。如果接口處理這個包，那麼到這裏結束。否則，向上傳遞這個包。</li><li>firewalld 默認動作。接受 icmp 包並拒絕其它的一切。</li></ol><p>這裏的關鍵信息是，源區域優先於接口區域。因此，對於多區域的 firewalld 配置的一般設計模式是，創建一個優先源區域來允許指定的 IP 對系統服務的提升訪問，並在一個限制性接口區域限制其它訪問。</p><h3 id="一個簡單的多區域示例" tabindex="-1">一個簡單的多區域示例 <a class="header-anchor" href="#一個簡單的多區域示例" aria-label="Permalink to “一個簡單的多區域示例”">​</a></h3><p>為演示優先權，讓我們在 <code>public</code> 區域中將 <code>http</code> 替換成 <code>ssh</code>，並且為我們喜歡的 IP 地址，如 1.1.1.1，設置一個默認的 <code>internal</code> 區域。以下的命令完成這個任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=public --remove-service=ssh</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --add-service=http</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --add-source=1.1.1.1</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>這些命令的結果是生成如下的配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=public --list-all</span></span>
<span class="line"><span>public (default, active)</span></span>
<span class="line"><span>  interfaces: eno1 eno2</span></span>
<span class="line"><span>  sources:</span></span>
<span class="line"><span>  services: dhcpv6-client http</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --get-target</span></span>
<span class="line"><span>default</span></span>
<span class="line"><span># firewall-cmd --zone=internal --list-all</span></span>
<span class="line"><span>internal (active)</span></span>
<span class="line"><span>  interfaces:</span></span>
<span class="line"><span>  sources: 1.1.1.1</span></span>
<span class="line"><span>  services: dhcpv6-client mdns samba-client ssh</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --get-target</span></span>
<span class="line"><span>default</span></span></code></pre></div><p>在上面的配置中，如果有人嘗試從 1.1.1.1 去 <code>ssh</code>，這個請求將會成功，因為這個源區域（<code>internal</code>）被首先應用，並且它允許 <code>ssh</code> 訪問。</p><p>如果有人嘗試從其它的地址，如 2.2.2.2，去訪問 <code>ssh</code>，它不是這個源區域的，因為和這個源區域不匹配。因此，這個請求被直接轉到接口區域（<code>public</code>），它沒有顯式處理 <code>ssh</code>，因為，public 的目標是 <code>default</code>，這個請求被傳遞到默認動作，它將被拒絕。</p><p>如果 1.1.1.1 嘗試進行 <code>http</code> 訪問會怎樣？源區域（<code>internal</code>）不允許它，但是，目標是 <code>default</code>，因此，請求將傳遞到接口區域（<code>public</code>），它被允許訪問。</p><p>現在，讓我們假設有人從 3.3.3.3 拖你的網站。要限制從那個 IP 的訪問，簡單地增加它到預定義的 <code>drop</code> 區域，正如其名，它將丟棄所有的連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=drop --add-source=3.3.3.3</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>下一次 3.3.3.3 嘗試去訪問你的網站，firewalld 將轉發請求到源區域（<code>drop</code>）。因為目標是 <code>DROP</code>，請求將被拒絕，並且它不會被轉發到接口區域（<code>public</code>）。</p><h3 id="一個實用的多區域示例" tabindex="-1">一個實用的多區域示例 <a class="header-anchor" href="#一個實用的多區域示例" aria-label="Permalink to “一個實用的多區域示例”">​</a></h3><p>假設你為你的組織的一台服務器配置防火牆。你希望允許全世界使用 <code>http</code> 和 <code>https</code> 的訪問，你的組織（1.1.0.0/16）和工作組（1.1.1.0/8）使用 <code>ssh</code> 訪問，並且你的工作組可以訪問 <code>samba</code> 服務。使用 firewalld 中的區域，你可以用一個很直觀的方式去實現這個配置。</p><p><code>public</code> 這個命名，它的邏輯似乎是把全世界訪問指定為公共區域，而 <code>internal</code> 區域用於為本地使用。從在 <code>public</code> 區域內設置使用 <code>http</code> 和 <code>https</code> 替換 <code>dhcpv6-client</code> 和 <code>ssh</code> 服務來開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=public --remove-service=dhcpv6-client</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --remove-service=ssh</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --add-service=http</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --add-service=https</span></span></code></pre></div><p>然後，取消 <code>internal</code> 區域的 <code>mdns</code>、<code>samba-client</code> 和 <code>dhcpv6-client</code> 服務（僅保留 <code>ssh</code>），並增加你的組織為源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=internal --remove-service=mdns</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --remove-service=samba-client</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --remove-service=dhcpv6-client</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --add-source=1.1.0.0/16</span></span></code></pre></div><p>為容納你提升的 <code>samba</code> 的權限，增加一個富規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=internal --add-rich-rule=&#39;rule family=ipv4 source address=&quot;1.1.1.0/8&quot; service name=&quot;samba&quot; accept&#39;</span></span></code></pre></div><p>最後，重新加載，把這些變化拉取到會話中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>僅剩下少數的細節了。從一個 <code>internal</code> 區域以外的 IP 去嘗試通過 <code>ssh</code> 到你的服務器，結果是回覆一個拒絕的消息。它是 firewalld 默認的。更為安全的作法是去顯示不活躍的 IP 行為並丟棄該連接。改變 <code>public</code> 區域的目標為 <code>DROP</code>，而不是 <code>default</code> 來實現它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=public --set-target=DROP</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>但是，等等，你不再可以 ping 了，甚至是從內部區域！並且 icmp （ping 使用的協議）並不在 firewalld 可以列入白名單的服務列表中。那是因為，icmp 是第 3 層的 IP 協議，它沒有端口的概念，不像那些捆綁了端口的服務。在設置公共區域為 <code>DROP</code> 之前，ping 能夠通過防火牆是因為你的 <code>default</code> 目標通過它到達防火牆的默認動作（default），即允許它通過。但現在它已經被刪除了。</p><p>為恢復內部網絡的 ping，使用一個富規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --permanent --zone=internal --add-rich-rule=&#39;rule protocol value=&quot;icmp&quot; accept&#39;</span></span>
<span class="line"><span># firewall-cmd --reload</span></span></code></pre></div><p>結果如下，這裏是兩個活動區域的配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=public --list-all</span></span>
<span class="line"><span>public (default, active)</span></span>
<span class="line"><span>  interfaces: eno1 eno2</span></span>
<span class="line"><span>  sources:</span></span>
<span class="line"><span>  services: http https</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=public --get-target</span></span>
<span class="line"><span>DROP</span></span>
<span class="line"><span># firewall-cmd --zone=internal --list-all</span></span>
<span class="line"><span>internal (active)</span></span>
<span class="line"><span>  interfaces:</span></span>
<span class="line"><span>  sources: 1.1.0.0/16</span></span>
<span class="line"><span>  services: ssh</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  masquerade: no</span></span>
<span class="line"><span>  forward-ports:</span></span>
<span class="line"><span>  icmp-blocks:</span></span>
<span class="line"><span>  rich rules:</span></span>
<span class="line"><span>        rule family=ipv4 source address=&quot;1.1.1.0/8&quot; service name=&quot;samba&quot; accept</span></span>
<span class="line"><span>        rule protocol value=&quot;icmp&quot; accept</span></span>
<span class="line"><span># firewall-cmd --permanent --zone=internal --get-target</span></span>
<span class="line"><span>default</span></span></code></pre></div><p>這個設置演示了一個三層嵌套的防火牆。最外層，<code>public</code>，是一個接口區域，包含全世界的訪問。緊接着的一層，<code>internal</code>，是一個源區域，包含你的組織，它是 <code>public</code> 的一個子集。最後，一個富規則增加到最內層，包含了你的工作組，它是 <code>internal</code> 的一個子集。</p><p>這裏的關鍵信息是，當在一個場景中可以突破到嵌套層，最外層將使用接口區域，接下來的將使用一個源區域，並且在源區域中額外使用富規則。</p><h3 id="調試" tabindex="-1">調試 <a class="header-anchor" href="#調試" aria-label="Permalink to “調試”">​</a></h3><p>firewalld 採用直觀範式來設計防火牆，但比它的前任 iptables 更容易產生歧義。如果產生無法預料的行為，或者為了更好地理解 firewalld 是怎麼工作的，則可以使用 iptables 描述 netfilter 是如何配置操作的。前一個示例的輸出如下，為了簡單起見，將輸出和日誌進行了修剪:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># iptables -S</span></span>
<span class="line"><span>-P INPUT ACCEPT</span></span>
<span class="line"><span>... (forward and output lines) ...</span></span>
<span class="line"><span>-N INPUT_ZONES</span></span>
<span class="line"><span>-N INPUT_ZONES_SOURCE</span></span>
<span class="line"><span>-N INPUT_direct</span></span>
<span class="line"><span>-N IN_internal</span></span>
<span class="line"><span>-N IN_internal_allow</span></span>
<span class="line"><span>-N IN_internal_deny</span></span>
<span class="line"><span>-N IN_public</span></span>
<span class="line"><span>-N IN_public_allow</span></span>
<span class="line"><span>-N IN_public_deny</span></span>
<span class="line"><span>-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT</span></span>
<span class="line"><span>-A INPUT -i lo -j ACCEPT</span></span>
<span class="line"><span>-A INPUT -j INPUT_ZONES_SOURCE</span></span>
<span class="line"><span>-A INPUT -j INPUT_ZONES</span></span>
<span class="line"><span>-A INPUT -p icmp -j ACCEPT</span></span>
<span class="line"><span>-A INPUT -m conntrack --ctstate INVALID -j DROP</span></span>
<span class="line"><span>-A INPUT -j REJECT --reject-with icmp-host-prohibited</span></span>
<span class="line"><span>... (forward and output lines) ...</span></span>
<span class="line"><span>-A INPUT_ZONES -i eno1 -j IN_public</span></span>
<span class="line"><span>-A INPUT_ZONES -i eno2 -j IN_public</span></span>
<span class="line"><span>-A INPUT_ZONES -j IN_public</span></span>
<span class="line"><span>-A INPUT_ZONES_SOURCE -s 1.1.0.0/16 -g IN_internal</span></span>
<span class="line"><span>-A IN_internal -j IN_internal_deny</span></span>
<span class="line"><span>-A IN_internal -j IN_internal_allow</span></span>
<span class="line"><span>-A IN_internal_allow -p tcp -m tcp --dport 22 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_internal_allow -s 1.1.1.0/8 -p udp -m udp --dport 137 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_internal_allow -s 1.1.1.0/8 -p udp -m udp --dport 138 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_internal_allow -s 1.1.1.0/8 -p tcp -m tcp --dport 139 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_internal_allow -s 1.1.1.0/8 -p tcp -m tcp --dport 445 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_internal_allow -p icmp -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_public -j IN_public_deny</span></span>
<span class="line"><span>-A IN_public -j IN_public_allow</span></span>
<span class="line"><span>-A IN_public -j DROP</span></span>
<span class="line"><span>-A IN_public_allow -p tcp -m tcp --dport 80 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span>-A IN_public_allow -p tcp -m tcp --dport 443 -m conntrack --ctstate NEW -j ACCEPT</span></span></code></pre></div><p>在上面的 iptables 輸出中，新的鏈（以 <code>-N</code> 開始的行）是被首先聲明的。剩下的規則是附加到（以 <code>-A</code> 開始的行） iptables 中的。已建立的連接和本地流量是允許通過的，並且入站包被轉到 <code>INPUT_ZONES_SOURCE</code> 鏈，在那裏如果存在相應的區域，IP 將被髮送到那個區域。從那之後，流量被轉到 <code>INPUT_ZONES</code> 鏈，從那裏它被路由到一個接口區域。如果在那裏它沒有被處理，icmp 是允許通過的，無效的被丟棄，並且其餘的都被拒絕。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>firewalld 是一個文檔不足的防火牆配置工具，它的功能遠比大多數人認識到的更為強大。以創新的區域範式，firewalld 允許系統管理員去分解流量到每個唯一處理它的分類中，簡化了配置過程。因為它直觀的設計和語法，它在實踐中不但被用於簡單的單一區域中也被用於複雜的多區域配置中。</p><hr>`,77)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.linuxjournal.com/content/understanding-firewalld-multi-zone-configurations?page=0,0"},{default:l(()=>[...s[0]||(s[0]=[a("https://www.linuxjournal.com/content/understanding-firewalld-multi-zone-configurations?page=0,0",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://www.linuxjournal.com/users/nathan-vance"},{default:l(()=>[...s[2]||(s[2]=[a("Nathan Vance",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),e(n,{href:"https://github.com/qhwdw"},{default:l(()=>[...s[3]||(s[3]=[a("qhwdw",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const C=i(o,[["render",h]]);export{v as __pageData,C as default};
